import { test } from 'node:test';
import assert from 'node:assert/strict';
import { frame, createState, BRICK_TOP, BALL_R } from './neon.js';

// Mock context for frame()
const mockCtx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {}
};

test('D1: Ball should bounce off brick (Missing Deflection)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Position ball to hit the top of the brick
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - BALL_R - 1, r: BALL_R, vx: 0, vy: 200 };

  const oldVy = state.ball.vy;
  frame(mockCtx, state);

  assert.notEqual(state.ball.vy, oldVy, 'Ball should have bounced (velocity changed)');
});

test('D3: Ball should not tunnel through bricks at high speed', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Use high speed to potentially tunnel
  // Level 10 speed: 1070 px/s. With dt=0.05, distance = 53.5.
  // We place the ball just above the brick and give it a huge velocity.
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - 2, r: BALL_R, vx: 0, vy: 2000 };

  // We simulate the movement and then the frame (which handles collisions)
  // But the current implementation does NOT handle movement in frame(), it's in step().
  // The problem is that step() happens, then frame() checks collisions.
  // If step() moves the ball completely across the brick, collides() will be false.

  // Let's simulate a high-speed frame:
  // 1. Move ball (step)
  // 2. Check collisions (frame)

  const dt = 0.05;
  // Current position: y = brick.y - 2.
  // New position: y = brick.y - 2 + 2000 * 0.05 = brick.y - 2 + 100 = brick.y + 98.
  // The brick is from y to y+20. The ball is now far below the brick.
  // collides() will be false.

  // We use a custom "step-and-frame" simulation
  import { step } from './neon.js';

  // This is tricky because we need to mock the state.
  const stateTunnel = createState(1);
  const brickT = stateTunnel.bricks[0];
  stateTunnel.ball = { x: brickT.x + brickT.w / 2, y: brickT.y - 2, r: BALL_R, vx: 0, vy: 2000 };

  step(stateTunnel, dt);
  frame(mockCtx, stateTunnel);

  assert.equal(brickT.alive, false, 'Brick should have been broken even at high speed');
});

