// Collision resolution: determines which face was hit, flips velocity, and pushes the ball out.
export function resolveCollision(state, brick) {
  const { ball } = state;

  // Calculate penetration depth on each axis
  const overlapX = Math.min(
    ball.x + ball.r - brick.x,
    brick.x + brick.w - (ball.x - ball.r)
  );
  const overlapY = Math.min(
    ball.y + ball.r - brick.y,
    brick.y + brick.h - (ball.y - ball.r)
  );

  // Corner case: if penetrations are nearly equal, it's a corner hit
  if (Math.abs(overlapX - overlapY) < 0.1) {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    // Push out on both axes (approximate)
    if (ball.vx > 0) ball.x -= overlapX; else ball.x += overlapX;
    if (ball.vy > 0) ball.y -= overlapY; else ball.y += overlapY;
    return;
  }

  if (overlapX < overlapY) {
    // Side hit: flip vx
    ball.vx = -ball.vx;
    // Push out
    if (ball.vx > 0) ball.x -= overlapX; else ball.x += overlapX;
  } else {
    // Top/Bottom hit: flip vy
    ball.vy = -ball.vy;
    // Push out
    if (ball.vy > 0) ball.y -= overlapY; else ball.y += overlapY;
  }
}

