  const bouge = () => state.ball.vx !== vx || state.ball.vy !== vy;

  frame(contexteFactice(), state);
  if (bouge()) return;

  step(state, dt);
  if (bouge()) {
    t.diagnostic('dévié par step() et non par frame()');
    return;
  }

  frame(contexteFactice(), state);
  if (bouge()) t.diagnostic('dévié par frame() après le déplacement de step()');
}
